widget=(ROOT/'app/src/main/java/com/wird/app/PrayerWidgetProvider.java').read_text()
def member(signature):
 a=widget.index(signature);b=widget.index('{',a);level=1;i=b+1
 while level:
  level+=(widget[i]=='{')-(widget[i]=='}');i+=1
 return widget[a:i]
